export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は、捨てなかった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "あの晩、あの人が駆け寄ったときには、相手はもう死んでいました。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯が目を上げた。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "あなたの一突きです。深すぎたのに、あなたは気づかなかった。白鷺門は傷を読むから、あの人はあなたの剣を持ち去ったんです。戸口のあの言葉は、あなたの代わりに刻んだものです。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "夜明けには、あの人は少しだけ遅れるつもりです。そうすれば、あなたがきれいな身のままここへ戻って、湯を沸かせるからって。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "言い終えた。思っていたよりずっと短かった。十年分の話も、注いでみれば小さな杯ひとつにしかならない。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯は動かなかった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "鞘に置いた手の、指の節が少しずつ白くなり、また少しずつゆるんでいった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "あいつが、お前に話したのか。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "はい。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "なぜ、お前に。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "私は数に入らないから、って。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯は一度だけ笑った。ごく短く、喉の奥で何かが切れたような笑いだった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "あいつは変わらないな。なんでも、いちばん値打ちのないところに置いていく。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ShenYan_Pained },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は立ち上がり、膝の上の剣を手に取って戸口へ行った。戸板に手をかけたまま、長いあいだ動かなかった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それから戸を押しあけて、外へ出ていった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "軒下に陸遅が立っていた。ふたりは肩を並べ、谷のほうを向いて立った。あいだに、人ひとりぶんの隔たりを残して。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満にはふたりが見えた。声は聞こえなかった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯が何か言った。ごく短く。陸遅は振り向かなかった。長い間をおいて、彼もひと言だけ返した。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それきり、どちらも口を開かなかった。軒のしずくがひとつ、またひとつ、ふたりのあいだの敷石に落ちた。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "空の端に最初の一筋の光がさしたとき、陸遅は腰の剣をはずして、差しだした。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯は長いあいだそれを見下ろしていたが、やがて受け取り、手にしていた黒鞘の剣を返した。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）十年、取り替えたままだった剣。元に戻すのには、ひと息しかかからなかった。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "陸遅は背を向け、石段を下りていった。一線関のほうではない。山の下へ。霧が彼を少しずつ呑みこんでいく。まず足、それから背中、最後に、あの無造作にかき上げた髪。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は振り返らなかった。沈硯も追わなかった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "師匠の部屋の戸が細く開き、またそっと閉まった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯は中へ戻り、剣を卓に置いて腰を下ろした。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "二煎目を。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は急須の中ですっかり冷めた一煎目を竹の溝へ捨て、あらためて湯を注いだ。今度は、手は震えなかった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "あの人、何て言ってました？", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "白鷺門へは行くな、と。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "じゃあ、あなたは何て？", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯は杯を持ち上げ、その底を見つめたまま、答えなかった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "関のほうから日が昇った。一線関には誰もいない。霧はゆっくりと晴れていき、そこで誰かを待つ者はいなかった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二振りの剣は、どちらも鞘の中にあった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）私はひと晩じゅう、お茶を注いでいた。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）あのひと言だけは、誰も私に注いでくれなかった。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.XiaoMan_Base },
];
